<script setup>
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, errorMessage } from '../services/api'
import { useCartStore } from '../stores/cart'
import { useFeedbackStore } from '../stores/feedback'
const route = useRoute(); const router = useRouter(); const cart = useCartStore(); const feedback = useFeedbackStore(); const product = ref(null); const color = ref(''); const size = ref(''); const quantity = ref(1); const loading = ref(true); const adding = ref(false)
onMounted(async () => { try { product.value = (await api.get(`/catalog/${route.params.ref}`)).data.product; quantity.value = product.value.quantityStep; color.value = product.value.colors[0] || ''; size.value = product.value.sizes[0] || '' } catch (e) { feedback.show(errorMessage(e), 'error'); router.replace('/catalogo') } finally { loading.value = false } })
async function add() { adding.value = true; try { await cart.add(product.value, color.value, size.value, quantity.value); feedback.show('Produto adicionado ao carrinho.') } catch(e) { feedback.show(errorMessage(e), 'error') } finally { adding.value = false } }
</script>
<template><div class="page"><v-btn to="/catalogo" variant="text" prepend-icon="mdi-arrow-left" class="mb-4">Voltar ao catálogo</v-btn><v-skeleton-loader v-if="loading" type="image, article" /><v-card v-else-if="product" class="soft-card pa-3"><v-row><v-col cols="12" md="6"><v-img :src="product.imageUrl" height="480" class="product-image rounded-xl" contain /></v-col><v-col cols="12" md="6" class="pa-6 pa-md-10"><div class="text-overline text-secondary font-weight-bold">{{ product.ref }} · {{ product.categoryLabel }}</div><h1 class="text-h3 font-weight-black mt-2 mb-3">{{ product.name }}</h1><p class="text-medium-emphasis">{{ product.description || product.type }}</p><div class="text-h4 font-weight-black my-7">{{ Number(product.price).toFixed(2) }} €</div><v-select v-if="product.colors.length" v-model="color" label="Cor" :items="product.colors" /><v-select v-if="product.sizes.length" v-model="size" label="Tamanho" :items="product.sizes" /><v-text-field v-model.number="quantity" type="number" label="Quantidade" :step="product.quantityStep" :min="product.quantityStep" :hint="`Múltiplos de ${product.quantityStep}`" persistent-hint /><v-btn color="primary" size="large" block class="mt-6" prepend-icon="mdi-cart-plus" :loading="adding" @click="add">Adicionar ao carrinho</v-btn></v-col></v-row></v-card></div></template>
